<?php if($wfReceipt['kind']==='document'):?><dt><?= $wfEsc($wfI('Ursprüngliche Vorlage')) ?></dt><dd><?= $wfEsc($wfOriginal['template_title']) ?> · <?= $wfEsc($wfI('Fassung')) ?> <?= $wfEsc($wfOriginal['template_version']) ?></dd><?php endif ?></dl>
<p><?= $wfEsc($wfI('Spätere Bearbeitungen ändern diese Bestätigung und ihre ursprünglichen Angaben nicht.')) ?></p>
