<details class="dwf-creation-original"><summary><?= $wfEsc($wfI('Vollständige ursprüngliche Angaben anzeigen')) ?></summary><p><?= $wfEsc($wfI('Diese Originaldaten enthalten die eingereichten Angaben und den beim Anlegen gespeicherten Stand mit seinen Feldkennungen und Quellen.')) ?></p><pre><?= $wfEsc(json_encode(['intent'=>$wfReceipt['intent'],'original'=>$wfOriginal],JSON_THROW_ON_ERROR|JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre></details>
</section>
<?php endif ?>
